solution.solution.cpp:
#include <cctype>
#include <map>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

struct Shortcut { int key{ 0 }; bool ctrl{ false }, shift{ false }, alt{ false }; };

namespace
{
    const std::vector<std::pair<std::string, int>>& names()
    {
        static const std::vector<std::pair<std::string, int>> n{
            { "Delete", 0x2E }, { "Insert", 0x2D }, { "Home", 0x24 }, { "End", 0x23 }, { "PageUp", 0x21 }, { "PageDown", 0x22 },
            { "Left", 0x25 }, { "Up", 0x26 }, { "Right", 0x27 }, { "Down", 0x28 }, { "Enter", 0x0D }, { "Esc", 0x1B },
            { "Space", 0x20 }, { "Tab", 0x09 } };
        return n;
    }

    std::string lower(std::string s) { for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return s; }

    std::string trim(const std::string& s)
    {
        const auto b{ s.find_first_not_of(' ') };
        if (b == std::string::npos) return "";
        return s.substr(b, s.find_last_not_of(' ') - b + 1);
    }

    bool keyFrom(const std::string& part, int& key)
    {
        const std::string p{ lower(part) };
        if (p.size() == 1 && std::isalnum(static_cast<unsigned char>(p[0]))) { key = std::toupper(static_cast<unsigned char>(p[0])); return true; }
        if (p.size() >= 2 && p[0] == 'f' && p.find_first_not_of("0123456789", 1) == std::string::npos)
        {
            const int n{ std::stoi(p.substr(1)) };
            if (n >= 1 && n <= 12 && p[1] != '0') { key = 0x70 + n - 1; return true; }
            return false;
        }
        for (const auto& [name, code] : names()) if (lower(name) == p) { key = code; return true; }
        return false;
    }
}

bool parseShortcut(const std::string& text, Shortcut& out)
{
    std::vector<std::string> parts;
    std::stringstream in{ text };
    for (std::string p; std::getline(in, p, '+');) parts.push_back(trim(p));
    if (parts.empty() || (!text.empty() && text.back() == '+')) return false;
    Shortcut s;
    for (std::size_t i{ 0 }; i + 1 < parts.size(); ++i)
    {
        const std::string m{ lower(parts[i]) };
        bool* flag{ m == "ctrl" || m == "control" ? &s.ctrl : m == "shift" ? &s.shift : m == "alt" ? &s.alt : nullptr };
        if (!flag || *flag) return false;
        *flag = true;
    }
    if (!keyFrom(parts.back(), s.key)) return false;
    out = s;
    return true;
}

std::string formatShortcut(const Shortcut& s)
{
    std::string out;
    if (s.ctrl) out += "Ctrl+";
    if (s.shift) out += "Shift+";
    if (s.alt) out += "Alt+";
    if ((s.key >= 'A' && s.key <= 'Z') || (s.key >= '0' && s.key <= '9')) return out + static_cast<char>(s.key);
    if (s.key >= 0x70 && s.key <= 0x7B) return out + "F" + std::to_string(s.key - 0x70 + 1);
    for (const auto& [name, code] : names()) if (code == s.key) return out + name;
    return out + "?";
}

std::vector<std::pair<std::string, std::string>> conflicts(const std::vector<std::pair<std::string, std::string>>& commands)
{
    std::vector<std::pair<std::string, std::string>> parsed;      // command, canonical shortcut
    for (const auto& [cmd, text] : commands)
    {
        Shortcut s;
        if (parseShortcut(text, s)) parsed.push_back({ cmd, formatShortcut(s) });
    }
    std::vector<std::pair<std::string, std::string>> out;
    for (std::size_t i{ 0 }; i < parsed.size(); ++i)
        for (std::size_t j{ i + 1 }; j < parsed.size(); ++j)
            if (parsed[i].second == parsed[j].second) out.push_back({ parsed[i].first, parsed[j].first });
    return out;
}

char mnemonic(const std::string& menuText)
{
    for (std::size_t i{ 0 }; i + 1 < menuText.size(); ++i)
    {
        if (menuText[i] != '&') continue;
        if (menuText[i + 1] == '&') { ++i; continue; }
        return static_cast<char>(std::toupper(static_cast<unsigned char>(menuText[i + 1])));
    }
    return 0;
}

unitTests:
using Pairs = std::vector<std::pair<std::string, std::string>>;
TEST("parsing") {
    Shortcut s; CHECK(parseShortcut("Ctrl+Shift+S", s)); CHECK_EQ(s.key, int('S')); CHECK(s.ctrl); CHECK(s.shift); CHECK(!s.alt);
    CHECK(parseShortcut("shift + control + f5", s)); CHECK_EQ(s.key, 0x74); CHECK(s.ctrl); CHECK(s.shift);
    CHECK(parseShortcut("Alt+PageDown", s)); CHECK_EQ(s.key, 0x22); CHECK(parseShortcut("Delete", s)); CHECK_EQ(s.key, 0x2E); CHECK(!s.ctrl);
    CHECK(parseShortcut("ctrl+7", s)); CHECK_EQ(s.key, int('7'));
}
TEST("bad shortcuts") { Shortcut s; CHECK(!parseShortcut("Ctrl+", s)); CHECK(!parseShortcut("Ctrl+Ctrl+S", s)); CHECK(!parseShortcut("Hyper+S", s)); CHECK(!parseShortcut("F13", s)); CHECK(!parseShortcut("Ctrl+SS", s)); CHECK(!parseShortcut("", s)); CHECK(!parseShortcut("F05", s)); }
TEST("formatting") {
    Shortcut s; parseShortcut("alt+shift+ctrl+pageup", s); CHECK_EQ(formatShortcut(s), std::string("Ctrl+Shift+Alt+PageUp"));
    parseShortcut("f12", s); CHECK_EQ(formatShortcut(s), std::string("F12")); parseShortcut("Ctrl+o", s); CHECK_EQ(formatShortcut(s), std::string("Ctrl+O"));
}
TEST("conflicts") {
    const Pairs cmds{ { "Save", "Ctrl+S" }, { "Search", "control+s" }, { "Open", "Ctrl+O" }, { "Broken", "Ctrl+?" }, { "Sync", "S+Ctrl" }, { "Stats", "ctrl + s" } };
    CHECK_EQ(conflicts(cmds), (Pairs{ { "Save", "Search" }, { "Save", "Stats" }, { "Search", "Stats" } }));
}
TEST("mnemonics") { CHECK_EQ(mnemonic("&Save"), 'S'); CHECK_EQ(mnemonic("E&xit"), 'X'); CHECK_EQ(mnemonic("Fish && &Chips"), 'C'); CHECK_EQ(mnemonic("No mnemonic"), char(0)); CHECK_EQ(mnemonic("Trailing&"), char(0)); }

